    "imageUrl": "https://www.camara.leg.br/midias/image/2026/11/img20260902154339550-768x473.jpeg",
    "imageCaption": "Deputado Coronel Meira, relator do projeto de lei",
    "imageCredit": "Renato Araújo / Câmara dos Deputados",
