    "imageUrl": "https://imagens.ebc.com.br/c_SedwTmAcZ6EjO2uJ1-K5NL75w=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/2026/11/15/cop31_negociacoes_avancam_mas_financiamento_e_desafio_para_2a_semana02.jpg?itok=NoaB1tVA",
